1	import type {WebSocket} from 'ws';
2	import type {ChatSession, SessionEntry} from '../../types/session.js';
3	import type {SessionLookup, SessionStore} from '../../types/sessionStore.js';
4	import type {ConnectedMessage} from '../../types/messages.js';
5	import {sendSkip, sendUpsert} from './sender.js';
6	import {log} from '../../shared/logger.js';
7	
8	/** Opt-in resume. GDPR: enabling it keeps conversation content past disconnect, so the consumer owns the retention bound — set it with the store's `maxAgeMs` and erasure methods and see re-cinq/HALEngine#41; an unbounded retained store is a retention breach, not a memory leak. */
9	export interface SessionResumeOptions {
10	  enabled: boolean;
11	  /** With no `?sessionId=`, rejoin the user's most recently active session (the store's `latestFor`) instead of starting one; `?new=1` still starts one. */
12	  latest?: boolean;
13	}
14	
15	/** What `onConnect` learns about a connection besides its session. */
16	export interface ConnectInfo {
17	  /** `true` when the connection rejoined a stored session, the one `?sessionId=` named or the user's latest; `false` for a new session. */
18	  resumed: boolean;
19	}
20	
21	interface Requester {
