```ts
const ANSWER_WITHIN_MS = 2000;

const recorder = (client: WebSocket) => {
  const frames: Frame[] = [];
  const waiting: Array<{types: string[]; resolve: (frame: Frame) => void}> = [];
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as Frame;
    frames.push(frame);
    for (const wait of waiting.splice(0)) {
      if (wait.types.includes(frame.type)) wait.resolve(frame);
    }
  });
  return {
    frames,
    // Fails naming what did arrive, so a red test reports the frames, not a bare timeout.
    next: (...types: string[]) =>
      new Promise<Frame>((resolve, reject) => {
        const seen = frames.find(frame => types.includes(frame.type));
        if (seen) {
          resolve(seen);
          return;
        }
        const timer = setTimeout(
          () => reject(new Error(`no ${types.join(' or ')} frame; the frames were ${JSON.stringify(frames.map(f => f.type))}`)),
          ANSWER_WITHIN_MS
        );
        timer.unref();
        waiting.push({types, resolve});
      }),
  };
};
```

Note: `frames.find` — resolves with the FIRST matching frame. For pong that's fine.

